import{_ as s,l as i,o as a,c as d,v as o,p as c,x as t,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"效应系统","description":"","frontmatter":{"title":"效应系统","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/effect-systems.md","filePath":"cs/effect-systems.md","lastUpdated":1789023840000}'),h={name:"cs/effect-systems.md"};function f(m,e,_,u,E,P){const r=i("Mermaid");return a(),d("div",null,[e[1]||(e[1]=o('<h1 id="效应系统" tabindex="-1">效应系统 <a class="header-anchor" href="#效应系统" aria-label="Permalink to &quot;效应系统&quot;">​</a></h1><div class="epigraph"><p>类型回答「值是什么」；效应回答「计算还做了什么」：抛异常、分配、IO、不确定。函数类型可带效应行，组合时取并。</p><footer>—— 据 Lucassen and Gifford, Polymorphic Effect Systems, 1988；Pierce TAPL 对效应的讨论；Leijen 行多态效应整理</footer></div><p>上一课<a href="/cs/lifetimes-regions">生命周期</a>跟踪指针活多久。缺口是<strong>计算的额外通道</strong>：<code>e : τ ! ε</code>。纯 STLC 的效应为空；<code>throw</code>、<code>print</code>、<code>alloc</code> 写入 ε。本课钉效应在类型上的位置，不把代数效应的全套 handler 语义写完。也不重写线性——线性管资源次数，效应管做了哪些动作。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HM 的 <code>a -&gt; a</code> 看不出会不会抛。Java 的 checked exception 是效应的粗粒度；ML 的 effect 系统（区域+读/写）服务优化与安全。缺口是<strong>函数类型上的 ε</strong>，以及子效应（少效应的函数可用在允许多效应的坑里——协变于效应集）。</p><p>行多态：<code>∀ρ. τ → τ ! {io | ρ}</code> 允许尚未点名的其它效应。这与<a href="/cs/typeclass-dictionary">类型类</a>的约束不同：效应常自动收集，不必实例搜索。</p><h3 id="效应不是「副作用」的散文同义词" tabindex="-1">效应不是「副作用」的散文同义词 <a class="header-anchor" href="#效应不是「副作用」的散文同义词" aria-label="Permalink to &quot;效应不是「副作用」的散文同义词&quot;">​</a></h3><p>未定义行为、数据竞争可以不在 ε 里。内存模型后课。本课的 ε 是语言声明的代数。</p><p><span class="marginnote">Lucassen–Gifford 1988。Talpin–Jouvelot。Koka / Eff / Frank 的代数效应是后继。Pierce 有短讨论。本课不把 Haskell <code>IO</code> 单子当唯一编码，尽管单子也能排效应序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规则：应用时合并两端效应；handler / <code>try</code> 从 ε 里减去已处理的标签。推断：与 W 同游，合一变成行合一（需处理 ρ）。优化：若 ε 空则可乱序或消除死代码（须健全）——中端课再用。</p>',11)),(a(),c(p,null,{default:t(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%CF%84%20%E2%86%92%20%CF%84'%20!%20%CE%B5%22%5D%20--%3E%20APP%5B%22%E5%BA%94%E7%94%A8%E5%B9%B6%E6%95%88%E5%BA%94%22%5D%0A%20%20APP%20--%3E%20H%5B%22handler%20%E5%87%8F%E5%8E%BB%E6%A0%87%E7%AD%BE%22%5D%0A%20%20H%20--%3E%20E2%5B%22%E5%89%A9%E4%BD%99%E6%95%88%E5%BA%94%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与区域：分配效应可指到区域，Tofte 系统把二者绑在一起。点名对照。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>子类型：<code>ε ⊆ ε&#39;</code> 则带 ε 的计算可用在期望 ε&#39; 处。多态效应避免「所有函数都标 IO」。不要把 Java <code>throws Exception</code> 当行多态。</p><p>代数效应的续延实现接到运行时 CPS 课；本课只要类型。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 handler 的深度语义。后课默认：函数类型可带效应行。下一课渐进类型：静态与动态的边界，效应与 tag 会相遇。</p><p>也不把「纯函数式编程」当已实现的效应系统。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>效应标注计算除结果外的动作；应用取并。</li><li>行多态避免把世界写成固定集合。</li><li>与线性、区域正交，可组合。</li><li>出处：Lucassen and Gifford, 1988；对照 Pierce；Leijen 行效应。</li></ul>',9))])}const B=s(h,[["render",f]]);export{T as __pageData,B as default};
